    SalesReport=async(data, columns)=>{
        let ReportContent = [];
        ReportContent.push({ image: "logo", height: 90, width: 550, margin: [0, -20, 0, 0] })
        // ReportContent.push({ text: 'JEF Techno Solutions Private Limited', style: 'PageHeader', margin: [106, -64, 0, 0] })
        ReportContent.push({ text: " Project Reference List", style: 'HeaderContent', margin: [0, 60, 0, 0] })
        let TableColumns = [
            { text: "Client Name", bold: true, style: 'tableHeaderContent' },
            { text: "Project Name", bold: true, style: 'tableHeaderContent' },
            { text: "PO Date", bold: true, style: 'tableHeaderContent' },
            { text: "WorkOrderNo", bold: true, style: 'tableHeaderContent' },
            { text: "PO No.", bold: true, style: 'tableHeaderContent' },
            { text: "Contact Person Name", bold: true, style: 'tableHeaderContent' },
            { text: "Contact No.", bold: true, style: 'tableHeaderContent' },
        ]
        let TableBodyContent = [];
        TableBodyContent.push(TableColumns);
        for (let j = 0; j < data.length; j++) {
            let rowData = data[j];
            TableBodyContent.push([
                { text: rowData["client_name"], style: 'centerAllignment' },
                { text: rowData["project_name"], style: 'centerAllignment' },
                { text: rowData["po_date"], style: 'centerAllignment' },
                { text: rowData["wo"], style: 'centerAllignment' },
                { text: rowData["pono"], style: 'centerAllignment' },
                { text: rowData["contact_person"], style: 'centerAllignment' },
                { text: rowData["contact_number"], style: 'centerAllignment' }
            ]);
        }
        // let totalWidth = 570;
        // let totalColumns = filteredColumns.length;
        // let columnWidth = parseInt(totalWidth / totalColumns);
    
        let calculatedWidths = [];
        for (let i = 0; i < TableColumns; i++) {
            calculatedWidths.push("*");
        }
        // console.log(calculatedWidths)
        ReportContent.push({
            margin: [0, 20, 0, 0],
            // layout: 'lightHorizontalLines',
            table: {
                headerRows: 1,
                width: calculatedWidths,
                // widths: [15, 35, 45, 40, 35, '*', 30],
                body: TableBodyContent
            }
        })
        var docDefinition = {
            name: "reports",
            pageSize: 'A4',
            pageOrientation: 'landscape', //landscape
            pageMargins: [40, 40, 40, 40],
            watermark: { text: 'JEF Techno Solutions Private Limited', fontSize: 20, italics: true, opacity: 0.06 },
            header: function (currentPage, pageCount) {
                return ({
                    columns: [
                        currentPage !== 1 ? 'JEF Techno Solutions Private Limited' : "",
                    ],
                    style: "FooterText",
                    margin: [40, 10, 40, 0],
                })
            },
            footer: function (currentPage, pageCount) {
                return ({
                    columns: [
                        'JEF Techno Solutions Private Limited',
                        { text: 'Page-' + currentPage.toString() + ' of ' + pageCount, alignment: 'right' }
                    ],
                    style: "FooterText",
                    margin: [40, 5, 40, 0],
                })
            },
            content: ReportContent,
            images: {
                logo: "https://www.jeftechno.com/salesvisit/weekly_plan/JEF_Logonew.png"
            },
            styles: {
                normal: {
                    fontSize: 12, alignment: 'left'
                }, PageHeader: {
                    fontSize: 20, alignment: 'center', color: "blue", bold: true
                }, HeaderContent: {
                    alignment: 'center', fontSize: 14, color: "#e32424", italics: true, bold: true
                }, tableHeaderContent: {
                    alignment: 'center', fontSize: 14, color: "#e32424"
                }, centerAllignment: {
                    alignment: 'center', fontSize: 12
                }, FooterText: {
                    fontSize: 6, color: "#e32424", italics: true
                }
            }
        }
        return docDefinition;
    }
